/* Clickable, block-width row. Used for menu items, demo lists etc.
 * Base is transparent so the parent surface shows through — works on cards
 * AND on muted page bg without ever vanishing (e.g. in dark theme where
 * --muted === --background, a --muted base would be invisible). */
.list-item {
  display: block;
  width: 100%;
  text-align: start;
  /* A PILL NEEDS MORE ROOM AT ITS ENDS THAN A RECTANGLE DOES, and a row that
     carries something on its trailing edge needs it most: at 12px a status
     Badge or a Code chip sat hard against the row's own curve and read as
     pressed into it (owner, 2026-08-31, on the pattern and archetype lists).
     16px is the first step that clears it, and it is the same step a Card gives
     its own content. */
  padding: var(--space-2) var(--space-4);
  background: transparent;
  color: var(--muted-foreground);
  /* The family's radius. Every pressable thing in this system is a full-radius
     pill, and a list row that rounded at 4px was the one that did not — the
     selected row in the components catalogue read as a rounded rectangle among
     pills (owner, 2026-08-31), the same finding the breadcrumb crumb produced
     two days earlier. */
  border-radius: var(--radius-full);
  /* Body size, the same as every other row a reader scans. It was --font-sm,
     which put a navigation column at 13px beside a 15px rail carrying the same
     kind of words (owner, 2026-08-31): a list is content, not a caption about
     content. */
  font-size: var(--font-base);
  transition: background var(--duration-fast), color var(--duration-fast);
}
.list-item:hover {
  background: var(--surface-hover);
  color: var(--foreground);
}
.list-item:active { background: var(--accent-soft); }
/* The ring, not a tint. Swapping the outline for a background made the keyboard
 * position identical to hover — the same pixels for "the pointer is here" and
 * "this is where you are", and at 1.09:1 neither read. SC 2.4.11 wants 3:1, and
 * only the ring delivers it on every surface a list can sit on. */
.list-item:focus-visible {
  background: var(--surface-hover);
  color: var(--foreground);
  outline: var(--focus-ring);
  outline-offset: var(--focus-ring-inset);
}
.list-item strong {
  color: var(--foreground);
  font-weight: var(--font-weight-semibold);
}
/* The row you are on, when the list is a switch between panes rather than navigation. Marked with
 * `aria-current` so the state a screen reader announces and the state you can see are the same
 * fact. A step DARKER than the hover tint above, so the selected row still reads as the selected
 * one while the pointer is somewhere else in the list. */
.list-item[aria-current] {
  background: var(--accent);
  color: var(--accent-foreground);
  font-weight: var(--font-weight-medium);
}

/* THE MARKED ROW. The glyph is a bullet with a direction: it sits on the first
 * line of the row (never centred in a two-line one) and keeps its size while
 * the words wrap. */
.list-item[data-icon] {
  display: flex;
  align-items: flex-start;
  gap: var(--space-2);
}
.list-item-marker {
  flex: none;
  color: var(--icon-muted);
}
/* THE BODY IS THE REST OF THE ROW, not the width of its words. The row is
 * already `width: 100%`; without `flex: 1` the body shrank to its content, so
 * anything laid out inside it — a title with its meta pushed to the far end, a
 * trailing action — had no room to be pushed to, and `justify: space-between`
 * silently did nothing (2026-08-29). `min-inline-size: 0` is what lets a long
 * title truncate instead of forcing the row wider than the list. */
.list-item-body { flex: 1; min-inline-size: 0; }
.list-item[data-icon]:hover .list-item-marker,
.list-item[data-icon]:focus-visible .list-item-marker { color: inherit; }

/* ── A labelled run of rows ─────────────────────────────────────────────────
   The heading separates from the rows by WEIGHT, CASE and AIR, not by colour:
   it sits in the same muted ink the rows do, because it is chrome like they
   are, and colouring it would make it compete with the row you are on. The step
   above each group after the first is what says a section ended; without it the
   label reads as another row with a smaller font. */
.list-group { display: flex; flex-direction: column; gap: var(--space-1); }
.list-group + .list-group { margin-block-start: var(--space-5); }
.list-group-label {
  /* Lines up with the rows under it, so the column has one left edge. */
  padding-inline: var(--space-4);
  padding-block-end: var(--space-1);
  font-size: var(--font-xs);
  font-weight: var(--font-weight-semibold);
  text-transform: uppercase;
  letter-spacing: var(--tracking-wide);
  /* FULL-STRENGTH INK, because a heading LEADS the rows under it. In the same
     muted grey the rows wear, a 12px label was smaller and no darker than what
     it introduced, and it receded instead: the owner read the group headings as
     blending into the ordinary items twice (2026-08-31), the second time after
     weight, case and tracking had already been added. <SideNav> keeps its
     labels muted and gets away with it because its rows carry icons and a
     label does not; a list of plain words has nothing else to tell them apart. */
  color: var(--foreground);
}

import './ListItem.css'
import { useId, type ButtonHTMLAttributes, type ReactNode } from 'react'
import { cn } from '../lib/cn'
import { Icon, type IconName } from '../Icon'

type Props = ButtonHTMLAttributes<HTMLButtonElement> & {
  /** A marker at the head of the row, so the rows read as a list. One icon
   *  for the whole list. */
  icon?: IconName
}

/**
 * One clickable row of a list: an optional marker, leading media, title, meta
 * and a trailing action, all inside the row's own hit area.
 */
export function ListItem({ className, type = 'button', icon, children, ...rest }: Props) {
  return (
    <button type={type} className={cn('list-item', className)} data-icon={icon ? '' : undefined} {...rest}>
      {icon && <Icon name={icon} size="sm" className="list-item-marker" aria-hidden="true" />}
      {icon ? <span className="list-item-body">{children}</span> : children}
    </button>
  )
}

/**
 * A LABELLED RUN OF ROWS, for a list long enough that the reader is looking for
 * a section before they look for a row. The heading is not one of the rows: it
 * is smaller, heavier, uppercase and tracked, and there is a step of air above
 * it, because a label that shares its size, weight and colour with the rows
 * under it is read as another row.
 *
 * That treatment is not new here. `<SideNav>` has drawn its group labels this
 * way since it was written, privately, and the second list that needed one
 * reached for an eyebrow instead and got a 12px medium grey label over 13px
 * regular grey rows, which the owner read off the components catalogue as
 * "headings that blend into the ordinary items" (2026-08-31). Second use is
 * what moves a thing into the system, so it moved.
 *
 * `role="group"` with the label as its name, so a screen reader announces which
 * section a row belongs to instead of a flat run of a hundred and forty.
 *
 * Copy: the label names the section in the reader's words, not the schema's,
 * and it is a noun — "Actions", not "Action components".
 */
export function ListGroup({ label, children, className }: { label: string; children: ReactNode; className?: string }) {
  const labelId = useId()
  return (
    <div className={cn('list-group', className)} role="group" aria-labelledby={labelId}>
      <div id={labelId} className="list-group-label">{label}</div>
      {children}
    </div>
  )
}
